3	import java.util.Locale;
4	
5	/**
6	 * Normalises a free-text owner {@code address} to a single canonical form.
7	 *
8	 * <p>Whitespace is trimmed and internal runs collapse to a single space, the text is upper-cased,
9	 * and common street-type abbreviations are expanded on whole tokens ({@code ST -> STREET},
10	 * {@code RD -> ROAD}, {@code AVE -> AVENUE}). So {@code "  12  main  st "} becomes
11	 * {@code "12 MAIN STREET"}. A {@code null} or whitespace-only value normalises to the empty string.
12	 */
13	final class AddressNormalizer {
14	
15	    private AddressNormalizer() {
16	    }
17	
18	    /**
19	     * Returns the canonical form of {@code raw}, or {@code ""} when it is {@code null} or blank once
20	     * whitespace is trimmed. The result is idempotent: normalising an already-normalised address
21	     * returns it unchanged.
22	     */
23	    static String normalize(String raw) {
24	        if (raw == null) {
25	            return "";
26	        }
27	        String cleaned = raw.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
28	        if (cleaned.isEmpty()) {
29	            return "";
30	        }
31	        String[] tokens = cleaned.split(" ");
32	        StringBuilder sb = new StringBuilder(cleaned.length());
33	        for (int i = 0; i < tokens.length; i++) {
34	            if (i > 0) {
35	                sb.append(' ');
36	            }
37	            sb.append(expand(tokens[i]));
38	        }
39	        return sb.toString();
40	    }
41	
42	    /** Expands a single upper-cased token if it is a known street-type abbreviation. */
43	    private static String expand(String token) {
44	        switch (token) {
45	            case "ST":
46	                return "STREET";
47	            case "RD":
48	                return "ROAD";
49	            case "AVE":
50	                return "AVENUE";
51	            default:
52	                return token;
53	        }
54	    }
55	}
