5	/**
6	 * Derives an owner's canonical region ('locality') from their postcode and city.
7	 *
8	 * <p>The postcode takes precedence: a 4-digit postcode falling in a known region's range
9	 * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) resolves the region directly. Only when the
10	 * postcode is absent or in no known range does derivation fall back to the fixed city-to-region
11	 * table. This yields the same region for known cities but disambiguates cities sharing a name.
12	 *
13	 * <p>Kept as a standalone class (not a method on {@link OwnerMapper}) so MapStruct does
14	 * not mistake it for an implicit {@code String -> String} mapping method and apply it to
15	 * every string property.
16	 */
17	public final class Locality {
18	
19	    /** Fixed city-to-region table. */
20	    private static final Map<String, String> CITY_REGION = Map.of(
21	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
22	
23	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
24	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
25	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
26	
27	    private Locality() {
28	    }
29	
30	    /**
31	     * The canonical region derived from {@code postcode} first, falling back to {@code city}.
32	     * Returns {@code "UNKNOWN"} when neither resolves a region.
33	     */
34	    public static String of(String city, String postcode) {
35	        String byPostcode = regionForPostcode(postcode);
36	        return byPostcode != null ? byPostcode : of(city);
37	    }
38	
39	    /** The canonical region for {@code city}, or {@code "UNKNOWN"} when it is not in the table. */
40	    public static String of(String city) {
41	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
42	    }
43	
44	    /**
45	     * The region carried by a {@code '<REGION>-<HASH8>'} customer code &mdash; its prefix up to the
46	     * first {@code '-'}. This is now the single source of an owner's locality, so the value derives
47	     * from the region-and-hash identity rather than being recomputed from city and postcode.
48	     * Returns {@code "UNKNOWN"} when the code is absent or carries no region prefix.
49	     */
50	    public static String ofCustomerCode(String customerCode) {
51	        if (customerCode == null) {
52	            return "UNKNOWN";
53	        }
54	        int dash = customerCode.indexOf('-');
55	        if (dash <= 0) {
56	            return "UNKNOWN";
57	        }
58	        return customerCode.substring(0, dash);
59	    }
60	
61	    /** The region whose range contains {@code postcode}, or {@code null} when none does. */
62	    private static String regionForPostcode(String postcode) {
63	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
64	            return null;
65	        }
66	        int value = Integer.parseInt(postcode);
67	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
68	            int[] range = entry.getValue();
69	            if (value >= range[0] && value <= range[1]) {
70	                return entry.getKey();
71	            }
72	        }
73	        return null;
74	    }
