1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * Duplicate-detection step of {@code POST /api/owners}: rejects the request 409 when the new owner
11	 * duplicates an existing one. Because the {@code householdId} is now deterministic &mdash; derived
12	 * from the last name and postcode (see {@link OwnerIdentity#householdId(String, String)}) &mdash;
13	 * two owners sharing a last name and postcode belong to the <em>same</em> household, and a second
14	 * such owner is a household duplicate.
15	 *
16	 * <p>Two independent conflicts are checked against every existing owner:
17	 * <ul>
18	 * <li><b>Exact identity</b>: the whole {@code identityKey}
19	 *   ({@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)}) matches.
20	 *   This always conflicts &mdash; a genuinely identical record is never allowed.</li>
21	 * <li><b>Household duplicate</b>: the computed {@code householdId} matches, i.e. the same last name
22	 *   and postcode. This is rejected <em>unless</em> the request opts in with
23	 *   {@code sharesHousehold: true}, in which case the new owner is admitted as a declared member of
24	 *   the household.</li>
25	 * </ul>
26	 *
27	 * <p>Runs after the normalize steps (so telephone is E.164 and email lower-cased) and before
28	 * {@link BuildOwner}, so no owner is persisted on conflict. The {@code householdId} is derived
29	 * exactly as {@link AssignHouseholdId} will later stamp it.
30	 */
31	public class RequireUniqueIdentity {
32	
33	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
34	            throws DuplicateIdentityException {
35	        String householdId = OwnerIdentity.householdId(request.getLastName(), request.getPostcode());
36	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
37	        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(), householdId);
38	        for (Owner existing : ownerRepository.findAll()) {
39	            String existingKey = OwnerIdentity.key(existing.getTelephone(), existing.getEmail(),
40	                    existing.getHouseholdId());
41	            if (identityKey.equals(existingKey)) {
42	                throw new DuplicateIdentityException(identityKey);
43	            }
44	            if (!sharesHousehold && householdId != null
45	                    && householdId.equals(existing.getHouseholdId())) {
46	                throw new DuplicateIdentityException(householdId);
47	            }
48	        }
49	    }
50	}
