1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	
10	/**
11	 * Step of {@code POST /api/owners}: flags a soft match. The new owner has already cleared the hard
12	 * duplicate check ({@link RequireUniqueIdentity}), so it is not a full identity duplicate. When it
13	 * nonetheless shares an existing owner's last name (compared case-insensitively) and postcode while
14	 * carrying a different telephone, it is still created but recorded as a possible duplicate: its
15	 * {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} to the matching owner's id
16	 * (the earliest-created match when there is more than one). Otherwise {@code possibleDuplicate} is
17	 * set false and {@code possibleDuplicateOf} left null.
18	 *
19	 * <p>A <em>declared</em> household member &mdash; one that opted in with {@code sharesHousehold} to
20	 * join an existing household (same last name and postcode) rather than be rejected as a household
21	 * duplicate &mdash; is never a suspected duplicate: its shared last name and postcode are exactly
22	 * what it declared, so it is left unflagged.
23	 *
24	 * <p>Runs after {@link BuildOwner} (so it can mutate the built owner in place) and before
25	 * {@link SaveOwner}, under the write transaction. A new owner with no postcode never soft-matches.
26	 */
27	public class FlagPossibleDuplicate {
28	
29	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
30	        owner.setPossibleDuplicate(false);
31	        owner.setPossibleDuplicateOf(null);
32	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
33	            return; // a declared household member is not a suspected duplicate
34	        }
35	        String postcode = owner.getPostcode();
36	        if (postcode == null || postcode.isBlank()) {
37	            return;
38	        }
39	        String lastName = normalize(owner.getLastName());
40	        String telephone = owner.getTelephone();
41	        Owner match = null;
42	        for (Owner existing : ownerRepository.findAll()) {
43	            if (!lastName.equals(normalize(existing.getLastName()))
44	                    || !postcode.equals(existing.getPostcode())) {
45	                continue;
46	            }
47	            if (telephone != null && telephone.equals(existing.getTelephone())) {
48	                continue; // same telephone is not a soft match
49	            }
50	            if (match == null || existing.getId() < match.getId()) {
51	                match = existing;
52	            }
53	        }
54	        if (match != null) {
55	            owner.setPossibleDuplicate(true);
56	            owner.setPossibleDuplicateOf(match.getId());
57	        }
58	    }
59	
60	    private static String normalize(String value) {
61	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
62	    }
63	}
